{
    // Checks /proc/self/environ to distinguish "not set" from "set to empty"
    // Required because .NET 9 treats empty env vars as unset on Linux.
    private static bool IsEnvironmentVariableDefined(string name)
    {
        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            return environ.Contains($"{name}=");
        }
        catch
        {
            return false;
        }
    }

